-- Tags (ADR 0001): the id is the {tagId} in the permanent URL /nfc/{tagId}.
-- Random, URL-safe (base64url), at least 128 bits; generated by src/tags/service.ts.

CREATE TABLE tags (
  id            text PRIMARY KEY,
  household_id  uuid NOT NULL REFERENCES households(id),
  -- Zero or one Chore at a time; re-pointing never touches the physical Tag.
  chore_id      uuid REFERENCES chores(id),
  created_at    timestamptz NOT NULL,
  created_by    uuid NOT NULL REFERENCES persons(id)
);

CREATE INDEX tags_household ON tags (household_id);
CREATE INDEX tags_chore ON tags (chore_id);

-- An NFC Completion records the Tag that was scanned (0002 left this without a FK).
ALTER TABLE completions
  ADD CONSTRAINT completions_tag_fk FOREIGN KEY (tag_id) REFERENCES tags(id);
